package main

// The other tools 'galopin launch' starts (goose, Mistral Vibe, Claude Code).
// Each is wired the way launchOpencode wires opencode: through galopin's local
// proxy (the tool holds only the proxy's secret, never the gateway credential),
// other providers' keys stripped, and no link to Cerea. Config for goose and
// Vibe is generated by the same code as the supervised engines' (goose_engine.go,
// vibe_engine.go) but written to a private temporary directory that is removed
// when the tool exits: the user's own goose and Vibe configuration is never read
// or written.

import (
	"context"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"time"

	"galopin/packaging"
)

// launchTempDir makes a private (0700) directory for one launch, beside where
// the opencode launch's TMPDIR lives (per-user, never a fixed name under /tmp).
func launchTempDir(stateDir, prefix string) (string, error) {
	parent := filepath.Dir(opencodeTmpDir(stateDir))
	if err := os.MkdirAll(parent, 0o700); err != nil {
		return "", err
	}
	return os.MkdirTemp(parent, prefix+"-")
}

// launchModels asks the gateway for the chat models this credential can use,
// like 'galopin goose setup' does. An empty catalogue is an error: the tool
// would have nothing to offer.
func (ls *launchSession) launchModels(ctx context.Context) ([]gatewayModel, error) {
	cctx, cancel := context.WithTimeout(ctx, modelsRefreshTimeout+30*time.Second)
	defer cancel()
	access, err := accessTokenFor(ls.credsPath, ls.creds)
	if err == nil {
		fctx, fcancel := context.WithTimeout(cctx, modelsRefreshTimeout)
		defer fcancel()
		if models := fetchModels(fctx, ls.creds.Gateway, access, ls.creds.Group); len(gooseModels(models)) > 0 {
			return models, nil
		}
	}
	return nil, fmt.Errorf("model discovery failed or listed no chat model (GET %s/models)", strings.TrimSuffix(ls.creds.Gateway, "/"))
}

// resolveToolBin picks the binary to run: an explicit path (or name) first,
// then each candidate in order, then the tool's name on PATH.
func resolveToolBin(explicit, name string, candidates ...string) (string, error) {
	if explicit != "" {
		if strings.ContainsRune(explicit, os.PathSeparator) {
			if fi, err := os.Stat(explicit); err != nil || fi.IsDir() {
				return "", fmt.Errorf("%s: not an executable file", explicit)
			}
			return explicit, nil
		}
		return exec.LookPath(explicit)
	}
	for _, c := range candidates {
		if c == "" {
			continue
		}
		if fi, err := os.Stat(c); err == nil && !fi.IsDir() {
			return c, nil
		}
	}
	p, err := exec.LookPath(name)
	if err != nil {
		return "", fmt.Errorf("%s not found: install it, or pass --%s PATH", name, name)
	}
	return p, nil
}

// pickLaunchModel is the model the tool starts on: --model when given (with a
// note when the gateway does not list it), else the first chat model, as the
// engines do.
func pickLaunchModel(requested string, ids []string, logf func(string, ...any)) string {
	if requested == "" {
		if len(ids) == 0 {
			return placeholderModelID
		}
		return ids[0]
	}
	for _, id := range ids {
		if id == requested {
			return requested
		}
	}
	logf("warning: --model %s is not in the gateway's model list", requested)
	return requested
}

func gooseIDs(models []gooseModel) []string {
	ids := make([]string, len(models))
	for i, m := range models {
		ids[i] = m.ID
	}
	return ids
}

// writeGooseLaunchConfig writes an interactive goose's config under root: the
// engine's provider file (without the session-id header, which tags usage as a
// Cerea session) and config.yaml (approve mode, keyring and telemetry off), and
// links the user's own session store so `goose session --resume` sees history.
func writeGooseLaunchConfig(root string, creds *credentials, models []gooseModel, model string) error {
	provider, err := gooseProviderJSON(fmt.Sprintf("127.0.0.1:%d", creds.ShimPort), creds.ShimSecret, models, false)
	if err != nil {
		return err
	}
	for _, d := range []string{"config/custom_providers", "data", "state"} {
		if err := os.MkdirAll(filepath.Join(root, d), 0o700); err != nil {
			return err
		}
	}
	if err := writeFileAtomic(filepath.Join(root, "config", "custom_providers", gooseProviderID+".json"), provider, 0o600); err != nil {
		return err
	}
	if err := writeFileAtomic(filepath.Join(root, "config", "config.yaml"), []byte(gooseEngineConfigYAML(model)), 0o600); err != nil {
		return err
	}
	return linkGooseSessions(root)
}

// launchGoose runs the user's own interactive goose against the gateway.
func launchGoose(ctx context.Context, opts launchOptions) error {
	ls, err := startLaunch(opts)
	if err != nil {
		return err
	}
	bin, err := resolveGooseLaunchBin(opts.gooseBin)
	if err != nil {
		return err
	}
	if got := gooseVersionOf(bin); got == "" {
		ls.logf("warning: could not read %s's version (galopin is tested against goose %s)", bin, packaging.GooseVersion())
	} else if got != packaging.GooseVersion() {
		ls.logf("warning: %s is goose %s; galopin is tested against %s", bin, got, packaging.GooseVersion())
	}
	if ls.creds.Mode == modeConnectors {
		return errors.New("this machine was enrolled with --connectors-only: it has no proxy for goose to use")
	}
	models, err := ls.launchModels(ctx)
	if err != nil {
		return err
	}
	gm := gooseModels(models)
	model := pickLaunchModel(opts.model, gooseIDs(gm), ls.logf)
	if err := ls.startProxy(opts); err != nil {
		return err
	}
	defer ls.close()

	root, err := launchTempDir(ls.stateDir, "goose-launch")
	if err != nil {
		return err
	}
	defer os.RemoveAll(root)
	creds := *ls.creds
	creds.ShimPort = ls.port
	if err := writeGooseLaunchConfig(root, &creds, gm, model); err != nil {
		return fmt.Errorf("writing the temporary goose config: %w", err)
	}
	env := gooseEnv(root, launchBaseEnv(opts))
	args := opts.args
	if len(args) == 0 {
		args = []string{"session"}
	}
	ls.logf("local goose (%s), billed to %s; not supervised by Cerea (no Plan/Ask/Auto, no review log)", model, billingLabel(ls.creds))
	ls.logf("goose asks before each tool call (approve mode), in this terminal; your own goose config and extensions are not loaded; galopin's own-state protections need galopin to answer and do not apply")
	return runLaunched(ctx, "goose", bin, args, env)
}

// resolveGooseLaunchBin: --goose, then the copy galopin installed (or the
// engine's override variable), then goose on PATH.
func resolveGooseLaunchBin(explicit string) (string, error) {
	var cands []string
	if b, err := gooseBinary(); err == nil {
		cands = append(cands, b)
	}
	return resolveToolBin(explicit, "goose", cands...)
}

func launchBaseEnv(opts launchOptions) []string {
	if opts.env != nil {
		return opts.env
	}
	return os.Environ()
}

// vibeVersionOf is the last word `bin --version` prints ("vibe 3.1.0" or "3.1.0").
func vibeVersionOf(bin string) string { return gooseVersionOf(bin) }

// resolveVibeLaunchBin: --vibe, then vibe on PATH, then the interactive entry
// point of the copy galopin installed (its venv holds `vibe` beside the
// `vibe-acp` the engine uses).
func resolveVibeLaunchBin(explicit string) (string, error) {
	if explicit != "" {
		return resolveToolBin(explicit, "vibe")
	}
	if p, err := exec.LookPath("vibe"); err == nil {
		return p, nil
	}
	var cands []string
	if exe, err := os.Executable(); err == nil {
		cands = append(cands, filepath.Join(filepath.Dir(exe), vibeInstallDirName, "venv", "bin", "vibe"))
	}
	return resolveToolBin("", "vibe", cands...)
}

// launchVibe runs the user's own interactive Mistral Vibe against the gateway.
func launchVibe(ctx context.Context, opts launchOptions) error {
	ls, err := startLaunch(opts)
	if err != nil {
		return err
	}
	bin, err := resolveVibeLaunchBin(opts.vibeBin)
	if err != nil {
		return err
	}
	if got := vibeVersionOf(bin); got == "" {
		ls.logf("warning: could not read %s's version (galopin is tested against Mistral Vibe %s)", bin, packaging.VibeVersion())
	} else if got != packaging.VibeVersion() {
		ls.logf("warning: %s is Mistral Vibe %s; galopin is tested against %s", bin, got, packaging.VibeVersion())
	}
	if ls.creds.Mode == modeConnectors {
		return errors.New("this machine was enrolled with --connectors-only: it has no proxy for Vibe to use")
	}
	models, err := ls.launchModels(ctx)
	if err != nil {
		return err
	}
	vm := vibeModels(models)
	if len(vm) == 0 {
		return errors.New("the gateway listed no chat model")
	}
	// The first model is Vibe's active one: put the chosen one first.
	if opts.model != "" {
		i := -1
		for j, m := range vm {
			if m.ID == opts.model {
				i = j
			}
		}
		if i < 0 {
			return fmt.Errorf("--model %s is not in the gateway's model list", opts.model)
		}
		vm[0], vm[i] = vm[i], vm[0]
	}
	if err := ls.startProxy(opts); err != nil {
		return err
	}
	defer ls.close()

	home, err := launchTempDir(ls.stateDir, "vibe-launch")
	if err != nil {
		return err
	}
	defer os.RemoveAll(home)
	if err := os.MkdirAll(filepath.Join(home, "logs"), 0o700); err != nil {
		return err
	}
	if err := writeFileAtomic(filepath.Join(home, "config.toml"), []byte(vibeConfigTOML(ls.shimAddr(), ls.creds.ShimSecret, vm)), 0o600); err != nil {
		return fmt.Errorf("writing the temporary Vibe config: %w", err)
	}
	if err := resetVibeTrust(home); err != nil {
		return err
	}
	env := vibeEnv(home, launchBaseEnv(opts))
	ls.logf("local Mistral Vibe (%s), billed to %s; not supervised by Cerea (no Plan/Ask/Auto, no review log)", vm[0].ID, billingLabel(ls.creds))
	ls.logf("Vibe asks before each tool call, in this terminal; your own ~/.vibe is not loaded (no folder is trusted); galopin's own-state protections need galopin to answer and do not apply")
	return runLaunched(ctx, "vibe", bin, opts.args, env)
}
